	if len(snapshots) == 0 {
		panic("WeightedScoring.Route: empty snapshots")
	}

	// EVOLVE-BLOCK-START
	// Compute composite scores from all scorers
	scores := make(map[string]float64, len(snapshots))
	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			// Clamp to [0,1] per INV-1
			if s < 0 {
				s = 0
			}
			if s > 1 {
				s = 1
			}
			scores[snap.ID] += s * ws.weights[i]
		}
	}

	// Compute load statistics for adaptive adjustments
	maxLoad := 0
	totalLoad := 0
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
		totalLoad += el
		if el > maxLoad {
			maxLoad = el
		}
	}
	avgLoad := float64(totalLoad) / float64(len(snapshots)+1)
	inputSize := len(req.InputTokens)

	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
		fEl := float64(el)

		// Quadratic load penalty - reduces tail latency
		if el > 0 {
			penalty := 1.0 / (1.0 + 0.2*fEl*fEl)
			scores[snap.ID] *= (0.25 + 0.75*penalty)
		}

		// Hard cutoff for instances far above average
		if fEl > avgLoad+3.0 && avgLoad > 0.5 {
			excess := (fEl - avgLoad) / (avgLoad + 1.0)
			scores[snap.ID] *= 0.1 / (0.1 + excess)
		}

		// Cache hit rate bonus
		scores[snap.ID] *= (0.82 + 0.18*snap.CacheHitRate)

		// KV pressure penalty - graduated
		if snap.KVUtilization > 0.7 {
			kvPenalty := (snap.KVUtilization - 0.7) / 0.3
			scores[snap.ID] *= (1.0 - 0.6*kvPenalty*kvPenalty)
		}

