		if inputSize > 256 && snap.FreeKVBlocks > 0 {
			memBonus := float64(snap.FreeKVBlocks) / float64(snap.FreeKVBlocks+200)
			scores[snap.ID] *= (1.0 + 0.12*memBonus)
		}

		// Floor
		if scores[snap.ID] < 0.001 {
			scores[snap.ID] = 0.001
		}
	}

